def rot_ref(mask):
 a=[list(row) for row in mask]; vars=[]
 for flip in (False,True):
  b=[row[::-1] for row in a] if flip else a
  for _ in range(4):
   vars.append(tuple(tuple(row) for row in b))
   b=[list(row) for row in zip(*b[::-1])]
 return vars

def shape_key(m):
 # allow rotation/reflection, dimensions normalized
 return min(rot_ref(m))
